style.css:
/* Estilo general */
body {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    background: #111827;
    color: white;
}

/* Título */
h1 {
    text-align: center;
    font-size: 40px;
    margin-top: 50px;
}

/* Botón personalizado */
button {
    display: block;
    margin: 30px auto;
    padding: 12px 25px;
    border: none;
    border-radius: 12px;
    background: #6366f1;
    color: white;
    font-size: 18px;
    cursor: pointer;
    transition: 0.3s;
}

button:hover {
    background: #818cf8;
    transform: scale(1.05);
}
